import java.util.*;
import java.io.*;

public class 나무높이 {
    static int answer;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine());
        for (int tc = 1; tc <= T; tc++) {
            sb.append("#").append(tc).append(" ");
            int N = Integer.parseInt(br.readLine());

            int[] trees = new int[N];
            int pivot = -1;
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int i = 0; i < N; i++) {
                trees[i] = Integer.parseInt(st.nextToken());
                pivot = Math.max(pivot, trees[i]);
            }

            int one = 0;
            int two = 0;
            int diff;
            for (int i = 0; i < N; i++) {
                diff = pivot - trees[i];
                one += diff % 2;
                two += diff / 2;
            }

            while (two - one >= 2) {
                one += 2;
                two--;
            }

            answer = Math.max(2 * one - 1, 2 * two);
            sb.append(answer).append("\n");
        } // tc end
        System.out.print(sb);
    } // main end

}

import java.util.*;
import java.io.*;

public class 보급로 {
    static final int INF = 1000000000; // 다익스트라 로직 구현을 위한 INF 값 설정
    // 상하좌우 탐색이 필요하므로 dy dx 선언
    static final int[] dy = { -1, 1, 0, 0 };
    static final int[] dx = { 0, 0, -1, 1 };

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        // 테케 수 입력
        StringTokenizer st = new StringTokenizer(br.readLine());
        int T = Integer.parseInt(st.nextToken());

        // 로직 구현
        for (int tc = 1; tc <= T; tc++) {

            // sb 출력형식 append
            sb.append("#").append(tc).append(" ");

            // 배열의 크기 N 입력
            st = new StringTokenizer(br.readLine());
            int N = Integer.parseInt(st.nextToken());

            // 배열 선언
            int[][] map = new int[N][N];
            // 우선 순위 큐 설정
            // type: {현재까지의 비용, 행 위치, 열 위치}
            PriorityQueue<int[]> q = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));

            // 각 노드별 시작점으로부터 거리 저장하는 dist 배열 선언
            int[][] dist = new int[N][N];

            // 각 지역별 dist INF로 설정
            for (int i = 0; i < N; i++) {
                Arrays.fill(dist[i], INF);
            }
            // 시작점은 0으로 설정
            dist[0][0] = 0;
            // 큐에 시작점 넣기
            q.offer(new int[] { 0, 0, 0 });

            // 각 지역의 깊이(가중치) 배열 입력
            for (int i = 0; i < N; i++) {
                String line = br.readLine();
                for (int j = 0; j < N; j++) {
                    map[i][j] = line.charAt(j) - '0';
                }
            }

            // 큐가 빌때까지 다익스트라 반복
            while (!q.isEmpty()) {
                // 우선순위 큐에서 가장 작은 값을 꺼낸다.
                int[] node = q.poll();
                int cost = node[0];
                int r = node[1];
                int c = node[2];

                // visited 처리 대신 현재 꺼낸 노드의 비용보다 더 적은 비용으로 처리됐다면 굳이 안봐도 됨
                if (cost > dist[r][c]) {
                    continue;
                }

                for (int i = 0; i < 4; i++) {
                    int nr = r + dy[i];
                    int nc = c + dx[i];
                    if (0 <= nr && nr < N && 0 <= nc && nc < N) { // 배열 범위 내에 있다면
                        // 다음 노드까지의 가중치 합
                        int newCost = cost + map[nr][nc];
                        // 더 적은 가중치가 되는 값을 해당 노드 위치의 dist에 저장
                        if (newCost < dist[nr][nc]) {
                            dist[nr][nc] = newCost;
                            q.offer(new int[] { newCost, nr, nc });
                        }
                    }
                }
            }
            sb.append(dist[N - 1][N - 1]).append("\n");
        }

        // sb에 모아서 한꺼번에 출력하기
        System.out.print(sb);
    }
}

import java.util.*;
import java.io.*;

public class 헌터 {

    static final int INF = 1000000000;
    static int[][] monsters;
    static int[][] customers;
    static int mobCount;
    static boolean[] hunted;
    static boolean[] visited;
    static StringBuilder sb;
    static int answer;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine().trim());
        for (int tc = 1; tc <= T; tc++) {
            sb.append('#').append(tc).append(' ');
            int N = Integer.parseInt(br.readLine().trim());

            monsters = new int[5][2];
            customers = new int[5][2];
            answer = INF;
            mobCount = 0;

            for (int i = 0; i < N; i++) {
                st = new StringTokenizer(br.readLine());
                for (int j = 0; j < N; j++) {
                    int point = Integer.parseInt(st.nextToken());
                    if (point > 0) {
                        monsters[point][0] = i;
                        monsters[point][1] = j;
                        mobCount++;
                    } else if (point < 0) {
                        customers[-point][0] = i;
                        customers[-point][1] = j;
                    } else
                        continue;
                }

            } // for i end

            hunted = new boolean[5];
            visited = new boolean[5];

            dfs(0, 0, 0, 0);

            sb.append(answer).append('\n');
        } // tc end
        System.out.print(sb);
    } // main end

    static void dfs(int x, int y, int depth, int dist) {
        if (dist >= answer) {
            return;
        }

        if (depth == mobCount * 2) {
            if (answer > dist)
                answer = dist;
            return;
        }

        int move = 0;
        for (int i = 1; i <= mobCount; i++) {
            if (!hunted[i]) {
                move = Math.abs(x - monsters[i][0]) + Math.abs(y - monsters[i][1]);
                hunted[i] = true;
                dfs(monsters[i][0], monsters[i][1], depth + 1, dist + move);
                hunted[i] = false;
            }
            if (hunted[i] && !visited[i]) {
                move = Math.abs(x - customers[i][0]) + Math.abs(y - customers[i][1]);
                visited[i] = true;
                dfs(customers[i][0], customers[i][1], depth + 1, dist + move);
                visited[i] = false;
            }
        } // for i end
    } // dfs end
} // class end

import java.io.*;
import java.util.*;

public class 선수과목 {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken()); // 과목 수 <= 1000
        int M = Integer.parseInt(st.nextToken()); // 선수 조건 수 <= 500000(입력 반복 수)

        int[] inDegree = new int[N + 1]; // 진입차수 관리 1번부터 사용
        int[] semester = new int[N + 1]; // 각 과목별 학기 관리: 진입차수에 따라 학기를 나눔

        List<Integer>[] graph = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 1; i <= M; i++) {
            st = new StringTokenizer(br.readLine());
            int A = Integer.parseInt(st.nextToken());
            int B = Integer.parseInt(st.nextToken());

            // A -> B 방향이므로 진입차수 증가, 인접리스트에 연결 정보 추가
            graph[A].add(B);
            inDegree[B]++;
        }

        // 현재 처리해도 되는 노드를 넣는다.(노드 번호: 과목 번호)
        Queue<Integer> q = new ArrayDeque<>();

        // 모든 과목의 진입차수에 따른 학기 확인
        for (int i = 1; i <= N; i++) {
            // 진입 차수가 0이면 먼저 들을 수 있는 과목이므로 1학기로 지정하고 q에 넣는다.
            if (inDegree[i] == 0) {
                semester[i] = 1;
                q.offer(i);
            }
        }

        // 학기 갱신하기
        while (!q.isEmpty()) {
            int subject = q.poll();

            // 현재 과목 이후 들을 수 있는 과목들 탐색
            for (int next : graph[subject]) {
                // 선수과목이 있는 과목이므로 학기 갱신: 이전 과목의 다음 학기에 듣는 것이 가장 빠른 시기라면 갱신
                // 간략하게 semester[next] = Math.max(semester[next], semester[subject] + 1) 가능
                if (semester[next] < semester[subject] + 1) {
                    semester[next] = semester[subject] + 1;
                }

                // 선수과목을 수강했으므로 이 과목을 수강하기 위해서 들어야하는 과목 수 감소
                inDegree[next]--;

                // 만약 진입차수가 0이 된다면 수강할 수 있으므로 q에 넣고 이후 과목 탐색
                if (inDegree[next] == 0) {
                    q.offer(next);
                }
            } // for end

        } // while end

        // 1번부터 N번까지 최소 몇 학기 수강인지 확인
        for (int i = 1; i <= N; i++) {
            sb.append(semester[i]).append(" ");
        }
        System.out.print(sb);

    } // main end
} // class end

import java.util.*;
import java.io.*;

public class 프로세서연결하기 {

    static class Core {
        int r; // 행 좌표
        int c; // 열 좌표

        Core(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    static final int[] dr = { 0, 1, 0, -1 };
    static final int[] dc = { 1, 0, -1, 0 };

    static int maxConnected; // 연결한 core 수
    static int minLength; // 전선 길이의 합(연결 코어 수 같다면 최소가 되어야함)
    static int N; // map 크기
    static int[][] map;
    static List<Core> cores; // 코어들을 담을 리스트

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        int T = Integer.parseInt(br.readLine());

        for (int tc = 1; tc <= T; tc++) {
            N = Integer.parseInt(br.readLine());

            maxConnected = 0;
            minLength = 145; // 최대 map 크기인 12x12 = 144 고려하여 초기값 설정
            map = new int[N][N];
            cores = new ArrayList<>();
            for (int i = 0; i < N; i++) {
                st = new StringTokenizer(br.readLine());
                for (int j = 0; j < N; j++) {
                    map[i][j] = Integer.parseInt(st.nextToken());

                    // 가장자리 코어는 이미 연결된 상태이므로 count하고 탐색은 하지 않는다.
                    if (map[i][j] == 1) {
                        // 가장자리 아닌 노드들만 저장
                        if (i != 0 && j != 0 && i != N - 1 && j != N - 1) {
                            cores.add(new Core(i, j));
                        }
                    } // if end

                } // for j end
            } // for i end

            dfs(0, 0, 0);
            sb.append('#').append(tc).append(' ').append(minLength).append('\n');
        } // tc end
        System.out.print(sb);
    } // main end

    // 탐색한 코어 수, 연결한 코어 수, 전선 길이 합
    static void dfs(int depth, int cntConnected, int lengthSum) {

        // 가지치기: 남은 코어 수만큼 연결 여부 결정해도 이전에 했던 결정의 코어 연결 수를 넘지 못하면 더이상 볼필요 없음
        // 남은 코어 수: cores.size() - depth
        if (cntConnected + cores.size() - depth < maxConnected) {
            return;
        }

        // 모든 코어 전선 연결 여부 확인했다면 갱신
        if (depth == cores.size()) { // 최대한 많은 코어 연결해야 하므로 maxConnected
            if (maxConnected < cntConnected) { // 코어 연결 수가 더 많다면 그걸로 갱신
                maxConnected = cntConnected;
                minLength = lengthSum;
            } else if (maxConnected == cntConnected) {
                if (minLength > lengthSum)
                    minLength = lengthSum;
            }

            return;
        }

        // cores에서 하나씩 빼면서 확인하기
        Core cur = cores.get(depth);

        // 각 방향마다 범위가 다르므로 모듈화하여 관리
        // 전선 연결 => 범위 저장해서 해당 범위 내에 들어오는 행 or 열이면 교차므로 return;

        for (int dir = 0; dir < 4; dir++) {
            // 좌, 우, 상, 하 방향 전선 연결 가능한지 확인
            if (canConnect(cur, dir)) {
                // 연결 가능하면 전선 길이 구하기
                int len = setWire(cur, dir, 1);
                dfs(depth + 1, cntConnected + 1, lengthSum + len);
                setWire(cur, dir, 0); // 경우의 수 상태 원복
            }
        }

        // 아무것도 연결x
        dfs(depth + 1, cntConnected, lengthSum);

    } // dfs end

    // 전선 연결 가능여부 확인
    static boolean canConnect(Core core, int dir) {
        int nr = core.r + dr[dir];
        int nc = core.c + dc[dir];

        while (inRange(nr, nc)) {
            if (map[nr][nc] != 0) { // 가는 경로에 이미 전선이 깔려있다면 깔지 못하므로 가지치기
                return false;
            }
            nr += dr[dir];
            nc += dc[dir];
        }

        return true;
    }

    // 전선 상태 변경
    static int setWire(Core core, int dir, int value) {

        int length = 0;
        int nr = core.r + dr[dir];
        int nc = core.c + dc[dir];

        // dr, dc 정의했으므로 방향별 순차 탐색
        while (inRange(nr, nc)) {
            map[nr][nc] = value;
            length++;

            nr += dr[dir];
            nc += dc[dir];
        }

        return length;
    } // setWire end

    // 가능한 범위인지 반환
    static boolean inRange(int nr, int nc) {
        return (0 <= nr && nr < N && 0 <= nc && nc < N);
    }

} // class end

import java.io.*;
import java.util.*;

/**
 * BOJ 17471 게리맨더링 (풀이 참고: https://seongkyun.github.io/baekjoon/2019/10/18/baekjoon/)
 *
 * 입력: 구역 수 N(2~10), 각 구역의 인구, 각 구역의 인접 구역 목록이다.
 * 테스트 케이스 수 T는 없다. 인접 관계는 양방향이다.
 * 출력: 두 선거구의 인구 차이 최솟값. 가능한 분할이 없으면 -1을 출력한다.
 * 두 선거구는 모두 비어 있지 않아야 하고, 각 선거구 안에서 서로 연결되어야 한다.
 *
 * 핵심 풀이: 비트마스크로 첫 선거구를 고르면 나머지는 두 번째 선거구다.
 * 1번 구역을 첫 선거구에 고정해 같은 분할을 두 번 검사하지 않는다.
 * 두 선거구 각각의 연결성을 확인한 뒤에만 인구 차이를 비교한다.
 * 인접 목록도 비트마스크이므로 연결성 검사는 O(N)이다.
 * 시간 복잡도 O(2^N * N), 공간 복잡도 O(N).
 * BOJ 제출 시 public class 이름을 Main으로 바꾼다.
 */
public class 지역구나누기 {
    private static int[] adjacent;

    private static boolean isConnected(int group) {
        int frontier = Integer.lowestOneBit(group);
        int visited = frontier;
        while (frontier != 0) {
            int currentBit = Integer.lowestOneBit(frontier);
            frontier ^= currentBit;
            int current = Integer.numberOfTrailingZeros(currentBit);
            int unvisitedNeighbors = adjacent[current] & group & ~visited;
            visited |= unvisitedNeighbors;
            frontier |= unvisitedNeighbors;
        }
        return visited == group;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] population = new int[n];
        int totalPopulation = 0;
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int district = 0; district < n; district++) {
            population[district] = Integer.parseInt(st.nextToken());
            totalPopulation += population[district];
        }

        adjacent = new int[n];
        for (int district = 0; district < n; district++) {
            st = new StringTokenizer(br.readLine());
            int count = Integer.parseInt(st.nextToken());
            for (int i = 0; i < count; i++) {
                int neighbor = Integer.parseInt(st.nextToken()) - 1;
                adjacent[district] |= 1 << neighbor;
            }
        }

        int allDistricts = (1 << n) - 1;
        int answer = Integer.MAX_VALUE;
        // 홀수 마스크에는 항상 1번 구역이 들어 있다. 전체 집합은 제외한다.
        for (int group = 1; group < allDistricts; group += 2) {
            int otherGroup = allDistricts ^ group;
            if (!isConnected(group) || !isConnected(otherGroup)) {
                continue;
            }

            int groupPopulation = 0;
            for (int district = 0; district < n; district++) {
                if ((group & (1 << district)) != 0) {
                    groupPopulation += population[district];
                }
            }
            answer = Math.min(answer, Math.abs(2 * groupPopulation - totalPopulation));
            if (answer == 0) {
                break;
            }
        }

        System.out.println(answer == Integer.MAX_VALUE ? -1 : answer);
    }
}

import java.io.*;
import java.util.*;

public class 키순서 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        StringTokenizer st;

        int T = Integer.parseInt(br.readLine().trim());
        for (int tc = 1; tc <= T; tc++) {
            sb.append("#").append(tc).append(" ");

            int N = Integer.parseInt(br.readLine().trim());
            int M = Integer.parseInt(br.readLine().trim());

            // 각 인덱스별 자신보다 크거나 작은 학생의 수(얼마나 알고 있는지) -> 이 수가 N - 1 이면 자신의 순서를 안다
            int[] known = new int[N + 1];
            // 각 인덱스마다 인접한 자신보다 작은 학생들을 원소로 가짐
            List<Integer>[] smallerThan = new ArrayList[N + 1];
            // 각 인덱스마다 인접한 자신보다 큰 학생들을 원소로 가짐
            List<Integer>[] tallerThan = new ArrayList[N + 1];

            for (int i = 1; i <= N; i++) {
                smallerThan[i] = new ArrayList<>();
                tallerThan[i] = new ArrayList<>();
            }

            // 인접 리스트에 원소 삽입
            for (int i = 0; i < M; i++) {
                st = new StringTokenizer(br.readLine());
                int a = Integer.parseInt(st.nextToken());
                int b = Integer.parseInt(st.nextToken());
                tallerThan[a].add(b);
                smallerThan[b].add(a);
            }

            Queue<Integer> smallQ = new ArrayDeque<>();
            Queue<Integer> tallQ = new ArrayDeque<>();

            // 각 학생을 시작점으로 두 방향 BFS를 돌리며 만나는 학생마다 known[시작점]++
            for (int i = 1; i <= N; i++) {
                boolean[] smallVisited = new boolean[N + 1];
                smallQ.offer(i);
                smallVisited[i] = true;

                // smaller bfs
                while (!smallQ.isEmpty()) {
                    int node = smallQ.poll();

                    // 인접 리스트가 비어 있으면 반복문이 0번 실행되므로 따로 분기하지 않는다
                    for (int next : smallerThan[node]) {
                        // 방문하지 않은 노드만 탐색
                        if (!smallVisited[next]) {
                            smallVisited[next] = true;
                            known[i]++;
                            smallQ.offer(next);
                        }
                    } // for next end
                } // smaller bfs end

                boolean[] tallVisited = new boolean[N + 1];
                tallQ.offer(i);
                tallVisited[i] = true;

                // taller bfs
                while (!tallQ.isEmpty()) {
                    int node = tallQ.poll();

                    for (int next : tallerThan[node]) {
                        // 방문하지 않은 노드만 탐색
                        if (!tallVisited[next]) {
                            tallVisited[next] = true;
                            known[i]++;
                            tallQ.offer(next);
                        }
                    } // for next end
                } // taller bfs end
            } // for i end

            // known이 N-1인 학생 수를 센다
            int count = 0;
            for (int i = 1; i <= N; i++) {
                if (known[i] == N - 1) {
                    count++;
                }
            }
            sb.append(count).append("\n");
        } // tc end
        System.out.print(sb);
    } // main end
}

import java.io.*;
import java.util.*;

public class 키순서플로이드 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();

        int T = Integer.parseInt(br.readLine().trim());
        for (int tc = 1; tc <= T; tc++) {
            int N = Integer.parseInt(br.readLine().trim());
            int M = Integer.parseInt(br.readLine().trim());

            // reachable[a][b] : a가 b보다 작다는 관계를 직접 또는 간접적으로 안다
            boolean[][] reachable = new boolean[N + 1][N + 1];
            for (int i = 0; i < M; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                int shorter = Integer.parseInt(st.nextToken());
                int taller = Integer.parseInt(st.nextToken());
                reachable[shorter][taller] = true;
            }

            // 경유 학생 via를 가장 바깥에 둬야 via 단계마다 관계가 빠짐없이 확정된다
            for (int via = 1; via <= N; via++) {
                for (int from = 1; from <= N; from++) {
                    // from이 via보다 작다는 사실을 모르면 via를 거쳐 갈 수 없다
                    if (!reachable[from][via]) {
                        continue;
                    }
                    for (int to = 1; to <= N; to++) {
                        if (reachable[via][to]) {
                            reachable[from][to] = true;
                        }
                    }
                }
            }

            int answer = 0;
            for (int student = 1; student <= N; student++) {
                int knownCount = 0;
                for (int other = 1; other <= N; other++) {
                    if (student == other) {
                        continue;
                    }
                    if (reachable[student][other] || reachable[other][student]) {
                        knownCount++;
                    }
                }
                // 자신을 제외한 N-1명 모두와의 관계를 알면 순서가 정해진다
                if (knownCount == N - 1) {
                    answer++;
                }
            }

            sb.append('#').append(tc).append(' ').append(answer).append('\n');
        } // tc end
        System.out.print(sb);
    } // main end
}

