/**
 * 사과 먹기 게임 복기본을 기준으로 한 풀이.
 *
 * 전제: N은 5 이상인 홀수이고, (0, 0)에서 동쪽을 보고 시작한다.
 * 직진과 제자리 우회전만 가능하며 회전 횟수의 합을 최소화한다.
 * 사과는 1번부터 차례로 나타나고 최대 10개이며 장애물은 없다.
 * 사과는 가장자리에 없고 연속한 사과는 서로 다른 행과 열에 있다.
 * 복기에서 N의 상한은 확인되지 않으므로 격자 전체는 저장하지 않는다.
 *
 * 입력: T, 각 사례의 N, N행의 격자. 사과 개수는 격자의 최대 번호이다.
 * 복기본 예제처럼 00000으로 붙인 행과 0 0 0 0 0 형태의 정수 행을 받는다.
 * 10번 사과의 붙여 쓰기 규칙은 복기에 없으므로 10이 있으면 공백으로 구분한다.
 * 출력: 사례마다 최소 회전 횟수만 한 줄에 출력한다. 사례 번호는 붙이지 않는다.
 *
 * 현재 방향을 기준으로 목표의 앞쪽 거리와 오른쪽 거리를 구한다.
 * 오른쪽 앞은 1회, 오른쪽 뒤는 2회, 왼쪽의 두 사분면은 3회가 필요하다.
 * 그보다 적게 회전하면 필요한 방향의 이동을 할 수 없으므로 하한이다.
 * 목표가 내부에 있어 빈 가장자리까지 우회할 공간이 있으므로 이 하한을 달성한다.
 * 도착 방향은 회전 횟수로 결정된다. 한 구간에서 더 회전하려는 경우에는
 * 그 회전을 사과 도착 직후로 미룰 수 있다. 이후의 최적 경로는 같은 상태에서
 * 계속할 수 있으므로 구간마다 최소 횟수만 선택하는 그리디가 성립한다.
 *
 * 사례당 시간 복잡도: O(N^2 + A), 추가 공간: O(A). 출력 버퍼는 별도이다.
 * A는 사과 개수이며 최대 10이다.
 */
public class 사과먹기게임 {
    // 방향을 시계 방향으로 나열하면 우회전 후 방향은 (방향 + 횟수) % 4이다.
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};
    private static final int MAX_APPLES = 10;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first = br.readLine();
        if (first == null) {
            return;
        }
        int testCases = Integer.parseInt(first.trim());

        StringBuilder answer = new StringBuilder();
        for (int testCase = 0; testCase < testCases; testCase++) {
            int size = Integer.parseInt(br.readLine().trim());
            int[] appleRow = new int[MAX_APPLES + 1];
            int[] appleCol = new int[MAX_APPLES + 1];
            int count = 0;
            for (int row = 0; row < size; row++) {
                count = Math.max(count, readBoardRow(br.readLine().trim(), size, row, appleRow, appleCol));
            }
            answer.append(minimumTurns(appleRow, appleCol, count)).append('\n');
        }
        System.out.print(answer);
    }

    private static int minimumTurns(int[] appleRow, int[] appleCol, int count) {
        int row = 0;
        int col = 0;
        int direction = 0;
        int total = 0;
        for (int number = 1; number <= count; number++) {
            int deltaRow = appleRow[number] - row;
            int deltaCol = appleCol[number] - col;
            int forward = deltaRow * DR[direction] + deltaCol * DC[direction];
            int rightDirection = (direction + 1) % 4;
            int right = deltaRow * DR[rightDirection] + deltaCol * DC[rightDirection];

            // 같은 행 또는 열인 연속 사과가 없으므로 두 상대 거리는 0이 아니다.
            int turns = right > 0 ? (forward > 0 ? 1 : 2) : 3;
            total += turns;
            direction = (direction + turns) % 4;
            row = appleRow[number];
            col = appleCol[number];
        }
        return total;
    }

    // 공백이 있으면 정수 행이고, 없으면 숫자를 붙여 쓴 행이다.
    private static int readBoardRow(String line, int size, int row, int[] appleRow, int[] appleCol) {
        boolean spaced = line.indexOf(' ') >= 0;
        StringTokenizer st = spaced ? new StringTokenizer(line) : null;
        int maximum = 0;
        for (int col = 0; col < size; col++) {
            int number = spaced ? Integer.parseInt(st.nextToken()) : line.charAt(col) - '0';
            if (number > 0) {
                appleRow[number] = row;
                appleCol[number] = col;
                maximum = Math.max(maximum, number);
            }
        }
        return maximum;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * 복기본의 본문과 그림으로 확인한 규칙을 구간 DP로 푼다.
 * 입력: T, 각 테스트의 N, 이어서 한 줄에 N개의 int 값.
 * 출력: 복기본의 예시처럼 각 테스트의 최대 점수만 한 줄에 출력한다. #번호는 붙이지 않는다.
 *
 * 현재 남은 풍선의 양쪽 이웃이 있으면 두 이웃 값의 곱을 얻는다.
 * 한쪽 이웃만 있으면 그 이웃 값, 마지막 풍선이면 자기 값을 얻는다.
 * 터뜨리는 풍선 자신의 값은 양쪽 이웃의 곱에 포함하지 않는다.
 *
 * dp[left][right]는 양 경계를 남긴 채 열린 구간 (left, right)를 모두 제거하는 최대 점수다.
 * last를 이 구간에서 마지막에 제거하면 그 전까지 last가 양쪽 부분 구간을 분리한다.
 * 따라서 두 부분 구간의 최댓값과 last를 제거하는 점수를 더해 최댓값을 구할 수 있다.
 *
 * N 상한과 값 범위는 제공되지 않았다. 시간 O(N^3), 공간 O(N^2)이므로 실제 제한 확인이 필요하다.
 * 곱, 각 부분 구간의 DP 값과 후보 합을 포함한 모든 중간 점수 계산이 long 범위에 들어온다고 가정한다.
 */
public class 풍선사격게임 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        StringBuilder output = new StringBuilder();
        int testCases = Integer.parseInt(br.readLine().trim());

        for (int testCase = 1; testCase <= testCases; testCase++) {
            int size = Integer.parseInt(br.readLine().trim());
            int[] values = new int[size + 2];
            st = new StringTokenizer(br.readLine());
            for (int index = 1; index <= size; index++) {
                values[index] = Integer.parseInt(st.nextToken());
            }
            output.append(maximumScore(values, size)).append('\n');
        }

        System.out.print(output);
    }

    private static long maximumScore(int[] values, int size) {
        // 실제 풍선은 1..size, 0과 size+1은 이웃의 부재를 나타내는 경계다.
        // 경계 배열 칸의 값은 사용하지 않으며, 값 1인 가상 풍선을 추가하지 않는다.
        long[][] dp = new long[size + 2][size + 2];

        // 빈 구간 dp[left][left+1]은 0. 작은 구간부터 채운다.
        for (int width = 2; width <= size + 1; width++) {
            for (int left = 0; left + width <= size + 1; left++) {
                int right = left + width;
                // 값 범위가 미제공이므로 비어 있지 않은 구간을 0점으로 초기화하지 않는다.
                long best = Long.MIN_VALUE;
                for (int last = left + 1; last < right; last++) {
                    long score;
                    if (left == 0 && right == size + 1) {
                        score = values[last];
                    } else if (left == 0) {
                        score = values[right];
                    } else if (right == size + 1) {
                        score = values[left];
                    } else {
                        score = (long) values[left] * values[right];
                    }
                    long candidate = dp[left][last] + dp[last][right] + score;
                    best = Math.max(best, candidate);
                }
                dp[left][right] = best;
            }
        }
        return dp[0][size + 1];
    }
}

import java.io.*;
import java.util.*;

/**
 * BOJ 17472 다리 만들기 2 (풀이 참고: https://velog.io/@protoss1025/%EB%B0%B1%EC%A4%80-17472-%EB%8B%A4%EB%A6%AC-%EB%A7%8C%EB%93%A4%EA%B8%B0-2)
 *
 * 입력: N M 다음에 0(바다), 1(땅)로 이루어진 지도가 N줄 주어진다.
 * 테스트 케이스 수 T는 없다. 섬은 상하좌우로 연결된 땅의 묶음이다.
 * 출력: 모든 섬을 연결하는 다리 길이 합의 최솟값. 불가능하면 -1이다.
 * 다리는 가로 또는 세로 직선이어야 하고 바다를 최소 2칸 지나야 한다.
 * 다리끼리 교차할 수 있지만 교차점에서 다른 다리로 갈아탈 수는 없다.
 *
 * 핵심 풀이: BFS로 섬 번호를 붙인 뒤 모든 땅에서 네 방향으로 직진한다.
 * 처음 만나는 다른 섬까지의 바다 길이가 2 이상일 때만 다리 후보로 삼는다.
 * 섬 쌍마다 가장 짧은 다리만 남기고 Kruskal로 최소 신장 트리를 구한다.
 * 선택한 다리가 섬 개수 - 1개보다 적으면 연결할 수 없는 섬이 있다.
 * 섬 수를 K라 할 때 시간 O(NM * max(N, M) + K^2 log K), 공간 O(NM + K^2).
 * BOJ 제출 시 public class 이름을 Main으로 바꾼다.
 */
public class 다리건설 {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};
    private static int n;
    private static int m;
    private static int[][] land;
    private static int[][] island;
    private static int[] parent;

    private static boolean inBounds(int row, int col) {
        return row >= 0 && row < n && col >= 0 && col < m;
    }

    private static int labelIslands() {
        int count = 0;
        Queue<Integer> queue = new ArrayDeque<>();
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < m; col++) {
                if (land[row][col] == 0 || island[row][col] != 0) {
                    continue;
                }
                island[row][col] = ++count;
                queue.offer(row * m + col);
                while (!queue.isEmpty()) {
                    int current = queue.poll();
                    int currentRow = current / m;
                    int currentCol = current % m;
                    for (int direction = 0; direction < 4; direction++) {
                        int nextRow = currentRow + DR[direction];
                        int nextCol = currentCol + DC[direction];
                        if (inBounds(nextRow, nextCol) && land[nextRow][nextCol] == 1
                                && island[nextRow][nextCol] == 0) {
                            island[nextRow][nextCol] = count;
                            queue.offer(nextRow * m + nextCol);
                        }
                    }
                }
            }
        }
        return count;
    }

    private static List<Edge> findBridges(int islandCount) {
        int[][] shortest = new int[islandCount + 1][islandCount + 1];
        for (int[] distances : shortest) {
            Arrays.fill(distances, Integer.MAX_VALUE);
        }
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < m; col++) {
                int from = island[row][col];
                if (from == 0) {
                    continue;
                }
                for (int direction = 0; direction < 4; direction++) {
                    int nextRow = row + DR[direction];
                    int nextCol = col + DC[direction];
                    int length = 0;
                    while (inBounds(nextRow, nextCol) && island[nextRow][nextCol] == 0) {
                        length++;
                        nextRow += DR[direction];
                        nextCol += DC[direction];
                    }
                    if (!inBounds(nextRow, nextCol)) {
                        continue;
                    }
                    int to = island[nextRow][nextCol];
                    // 중간에 땅을 만났다면 그 뒤의 섬까지 다리를 연장할 수 없다.
                    if (to != from && length >= 2) {
                        shortest[from][to] = Math.min(shortest[from][to], length);
                        shortest[to][from] = Math.min(shortest[to][from], length);
                    }
                }
            }
        }

        List<Edge> edges = new ArrayList<>();
        for (int from = 1; from <= islandCount; from++) {
            for (int to = from + 1; to <= islandCount; to++) {
                if (shortest[from][to] != Integer.MAX_VALUE) {
                    edges.add(new Edge(from, to, shortest[from][to]));
                }
            }
        }
        return edges;
    }

    private static int find(int islandNumber) {
        if (parent[islandNumber] != islandNumber) {
            parent[islandNumber] = find(parent[islandNumber]);
        }
        return parent[islandNumber];
    }

    private static class Edge implements Comparable<Edge> {
        final int from;
        final int to;
        final int length;

        Edge(int from, int to, int length) {
            this.from = from;
            this.to = to;
            this.length = length;
        }

        @Override
        public int compareTo(Edge other) {
            return Integer.compare(length, other.length);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        land = new int[n][m];
        island = new int[n][m];
        for (int row = 0; row < n; row++) {
            st = new StringTokenizer(br.readLine());
            for (int col = 0; col < m; col++) {
                land[row][col] = Integer.parseInt(st.nextToken());
            }
        }

        int islandCount = labelIslands();
        List<Edge> edges = findBridges(islandCount);
        Collections.sort(edges);
        parent = new int[islandCount + 1];
        for (int i = 1; i <= islandCount; i++) {
            parent[i] = i;
        }

        int selected = 0;
        int totalLength = 0;
        for (Edge edge : edges) {
            int fromRoot = find(edge.from);
            int toRoot = find(edge.to);
            if (fromRoot == toRoot) {
                continue;
            }
            parent[toRoot] = fromRoot;
            totalLength += edge.length;
            if (++selected == islandCount - 1) {
                break;
            }
        }
        System.out.println(selected == islandCount - 1 ? totalLength : -1);
    }
}
